-- Migration: 018_invoice_numbers
-- Non-destructive additions for TVA-compliant invoicing.
-- Adds a per-tenant sequential invoice number to transactions (nullable — only
-- set when a formal invoice is explicitly generated by the cashier for a sale).
-- Idempotent (safe to run multiple times).
-- Depends on: 007_tenants_and_licenses, 013_remaining_tables (transactions),
--             015_receipt_numbers (establishes the atomic counter pattern)

-- ─── 1. Invoice number column on transactions ────────────────────────────
-- Nullable: most sales do not produce a formal invoice. A non-null value
-- means POST /invoices/generate was called for this transaction.
ALTER TABLE transactions
  ADD COLUMN IF NOT EXISTS invoice_number TEXT;

-- ─── 2. Per-tenant invoice counter ───────────────────────────────────────
-- One row per tenant. Incremented atomically via INSERT … ON CONFLICT DO
-- UPDATE … RETURNING (row-locked on conflict → no gap, no collision).
-- Format produced by the application: F-000001 (F prefix, 6-digit zero-padded).
CREATE TABLE IF NOT EXISTS tenant_invoice_counters (
  tenant_id  UUID PRIMARY KEY,
  last_seq   BIGINT NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── 3. Uniqueness of invoice numbers within a tenant ────────────────────
-- Partial index: only non-null rows participate, keeping the index small.
CREATE UNIQUE INDEX IF NOT EXISTS idx_transactions_invoice_per_tenant
  ON transactions(tenant_id, invoice_number)
  WHERE invoice_number IS NOT NULL;
